values
  ('easy-arrays-two-sum', 'Two Sum Training', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Return the indices of two numbers that add up to the target.', '[{"input":"nums = [2,7,11,15], target = 9","output":"[0,1]"},{"input":"nums = [3,2,4], target = 6","output":"[1,2]"}]'::jsonb, '{"python":"def solve(nums, target):\n    return []\n","javascript":"export function solve(nums, target) {\n  return []\n}\n"}'::jsonb, true),
  ('easy-strings-palindrome', 'Clean Palindrome', 'easy'::public.question_difficulty, 'strings'::public.question_topic, 'Return true if the lowercase alphanumeric characters form a palindrome.', '[{"input":"s = \"Race car!\"","output":"true"},{"input":"s = \"debug\"","output":"false"}]'::jsonb, '{"python":"def solve(s):\n    return False\n","javascript":"export function solve(s) {\n  return false\n}\n"}'::jsonb, true),
