  ('medium-arrays-longest-streak', 'Longest Clean Streak', 'medium'::public.question_difficulty, 'arrays'::public.question_topic, 'Given daily score changes, return the maximum total score from one contiguous streak.', '[{"input":"nums = [1,2,3,4]","output":"10"},{"input":"nums = [2,-1,2,3]","output":"6"}]'::jsonb, '{"python":"def solve(nums):\n    return 0\n","javascript":"export function solve(nums) {\n  return 0\n}\n"}'::jsonb, true),
  ('medium-strings-group-anagrams', 'Anagram Boxes', 'medium'::public.question_difficulty, 'strings'::public.question_topic, 'Group words that contain the same letters and return the number of groups.', '[{"input":"words = [\"eat\",\"tea\",\"tan\",\"ate\"]","output":"2"},{"input":"words = [\"abc\",\"bca\",\"cab\",\"dog\"]","output":"2"}]'::jsonb, '{"python":"def solve(words):\n    return 0\n","javascript":"export function solve(words) {\n  return 0\n}\n"}'::jsonb, true),
  ('medium-trees-level-sum', 'Best Tree Level', 'medium'::public.question_difficulty, 'trees'::public.question_topic, 'Given level-order tree values with null gaps, return the level with the largest sum.', '[{"input":"root = [1,7,0,7,-8,null,null]","output":"2"},{"input":"root = [5,3,8]","output":"2"}]'::jsonb, '{"python":"def solve(root):\n    return 0\n","javascript":"export function solve(root) {\n  return 0\n}\n"}'::jsonb, true),
  ('medium-graphs-island-count', 'Island Counter', 'medium'::public.question_difficulty, 'graphs'::public.question_topic, 'Return the number of connected land groups in a grid.', '[{"input":"grid = [[1,1,0],[0,1,0],[1,0,1]]","output":"3"},{"input":"grid = [[1,1],[1,1]]","output":"1"}]'::jsonb, '{"python":"def solve(grid):\n    return 0\n","javascript":"export function solve(grid) {\n  return 0\n}\n"}'::jsonb, true),
